import { z } from "zod";
import { optionalText } from "./common";

// A badge definition. Four types exist; the panel creates two of them:
//
//   normal       awarded for a workout or a challenge that points at it
//   manual       given by hand, or claimed with a code or link ("event")
//   milestone    generated by the backend for repeat counts; edited, not created
//   perfections  generated for 100% completions; edited, not created

export const badgeSchema = z.looseObject({
	id: z.string(),
	etag: z.string(),
	name: z.string(),
	/** "normal" badges are the ones a workout or a challenge can award. */
	type: z.string(),
	imageRelativePath: z.string(),
	/** Note for the team. */
	comment: optionalText,
	isHidden: z.boolean().nullish().default(false),
	/**
	 * Where the app lists the badge. Worked out by the server (for a normal
	 * badge, from what it is assigned to); never set by the panel.
	 */
	sectionId: optionalText,
	subsectionId: optionalText,
	/** Manual badges only: "event" or "specialTraining". */
	specialCategory: optionalText,
	/** Milestone badges only. */
	repeatCategory: optionalText,
	milestoneCount: z.number().nullish().default(null),
	activeFromUtc: optionalText,
	activeTillUtc: optionalText,
	/** Event badges only: the code in the link or QR that claims the badge. */
	claimToken: optionalText,
	isClaimLinkActive: z.boolean().nullish().default(false),
	createdAtUtc: z.string().default(""),
	updatedAtUtc: z.string().default(""),
});
export type Badge = z.infer<typeof badgeSchema>;

/** What a create request carries: everything the server does not assign. */
export const newBadgeSchema = badgeSchema.omit({
	id: true,
	etag: true,
	sectionId: true,
	subsectionId: true,
	createdAtUtc: true,
	updatedAtUtc: true,
});
export type NewBadge = z.infer<typeof newBadgeSchema>;

export function blankBadge(): NewBadge {
	return {
		name: "",
		type: "normal",
		imageRelativePath: "",
		comment: null,
		isHidden: false,
		specialCategory: null,
		repeatCategory: null,
		milestoneCount: null,
		activeFromUtc: null,
		activeTillUtc: null,
		claimToken: null,
		isClaimLinkActive: false,
	};
}
